service.method:

UPDATE SSIAD
SET SMR_STATUS = ${SMR_STATUS}
, CHANGE_DATE = ${current.DATE}
, CHANGE_TIME = ${current.TIME}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND NVL(DEL_FLAG,'N') = 'N'
	AND SMR_NUMBER = ${SMR_NUMBER}


		INSERT INTO SAPPP (
			HOUSE_CODE
			,COMPANY_CODE
			,SMR_NUMBER
			,SEQ
			,RECENT
			,APP_STATUS
			,APPLY_FOR
			,ADD_DATE
			,ADD_TIME
			,CONFIRM_USER_ID
			,APP_COMMENT
			,POSTPROCESSED
			,APP_NO
			,APP_NO_SEQ
			,APP_LINE_SEQ
			,RE_FLAG
		) VALUES (
			${session.HOUSE_CODE}
			,${session.COMPANY_CODE}
			,${SMR_NUMBER}
			,CONVERT(CONVERT(#DB_OWNER#NVL(
                  (SELECT appp.SEQ
                  FROM SAPPP appp
                  WHERE appp.HOUSE_CODE = ${session.HOUSE_CODE}
                      AND appp.COMPANY_CODE = ${session.COMPANY_CODE}
                      AND appp.SMR_NUMBER = ${SMR_NUMBER})
            , '0'), INT) + 1, VARCHAR(10))
		    ,${RECENT}
			,${APP_STATUS}
			,${APPLY_FOR}
			,${current.DATE}
			,${current.TIME}
			,${session.ID}
			,${APP_COMMENT}
			,${POSTPROCESSED}
			,(SELECT DISTINCT APP_NO FROM SGWGL WHERE SUX_WKEY1 = ${SMR_NUMBER} ORDER BY APP_NO DESC LIMIT 1)
			,${APP_NO_SEQ}
			,${APP_LINE_SEQ}
			,${RE_FLAG}
		)


DELETE FROM SPMGT
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND CONT_NO = ${SMR_NUMBER}
	AND ACTION = ${ACTION}


	    INSERT INTO SPMGT (
			HOUSE_CODE
			,COMPANY_CODE
			,CONT_NO
			,CONT_GL_SEQ
			,SEQ
			,ADD_DATE
			,ADD_TIME
			,USER_COMPANY_CODE
			,USER_ID
			,ACTION
			,IP
	    ) VALUES (
            ${session.HOUSE_CODE}
            ,${session.COMPANY_CODE}
            ,${SMR_NUMBER}
            ,'1'
            ,CONVERT(CONVERT(#DB_OWNER#NVL(
	        	(SELECT SEQ
	        	 FROM SPMGT pmgt
	 	         WHERE pmgt.HOUSE_CODE = ${session.HOUSE_CODE}
		            AND pmgt.COMPANY_CODE = ${session.COMPANY_CODE}
		            AND pmgt.CONT_NO = ${SMR_NUMBER})
			, '0'), INT) + 1, VARCHAR(10))
			,${current.DATE}
			,${current.TIME}
			,${session.COMPANY_CODE}
			,'BATCH'
			,${ACTION}
			,${IP}
	    )


SELECT 
	APP_NO
FROM 
	SGWGL 
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SUX_WKEY1 = ${SMR_NUMBER}
ORDER BY
	APP_NO DESC
